        const DataType& lagrange_last() const { return data[16]; }
        DataType& q_delta_range() { return data[17]; }
        const DataType& q_delta_range() const { return data[17]; }
        DataType& lagrange_ecc_op() { return data[18]; }
        const DataType& lagrange_ecc_op() const { return data[18]; }
        DataType& q_poseidon2_external() { return data[19]; }
        const DataType& q_poseidon2_external() const { return data[19]; }
        DataType& q_poseidon2_external_initial() { return data[20]; }
        const DataType& q_poseidon2_external_initial() const { return data[20]; }
        DataType& q_poseidon2_quad_internal() { return data[21]; }
        const DataType& q_poseidon2_quad_internal() const { return data[21]; }
        DataType& q_5() { return data[22]; }
        const DataType& q_5() const { return data[22]; }
